import numpy as np, base64, subprocess, json

def make_pcm(x, encoding='int16'):
    x = np.clip(x, -1, 1)
    if encoding=='int16':
        return base64.b64encode((x*32767).astype('<i2').tobytes()).decode()
    else:
        return base64.b64encode(x.astype('<f4').tobytes()).decode()

def call(tool, args):
    r = subprocess.run(['ft2','call',tool,json.dumps(args)], capture_output=True, text=True)
